// Reads the change under test from git: added lines per file, git status per path, and every removed line.
// Git is spawned with Bun.spawnSync like script/check-spawn-imports.ts; no spawning module is imported.

import { readFileSync, statSync } from "node:fs"
import path from "node:path"

export type Added = { line: number; text: string }

export type Change = {
  path: string
  // Git status letter: A, M, D, R, C or T.
  status: string
  from: string | undefined
  added: Added[]
  // New git mode (100644 file, 100755 executable, 120000 symlink, 160000 submodule). Absent means a plain file.
  mode?: string
  // Size in bytes of the new blob. Absent for deletions and submodules.
  size?: number
  // git treats the file as binary (numstat reports it without line counts).
  binary?: boolean
  // The file starts with a #! line. Only read for executable files.
  shebang?: boolean
  // Trimmed text of the lines the change removes from this file.
  removedLines?: string[]
}

export type Diff = {
  changes: Change[]
  // Trimmed text of every removed line with how many times it was removed. An added line identical to a removed one is
  // moved code, not new code, but each removal excuses one added line only.
  removed: Map<string, number>
}

const MAX_UNTRACKED_BYTES = 1_000_000

export function git(cwd: string, args: string[]) {
  const result = Bun.spawnSync(["git", "-C", cwd, ...args])
  if (result.exitCode !== 0) throw new Error(`git ${args.join(" ")} failed: ${result.stderr.toString().trim()}`)
  return result.stdout.toString()
}

export function tryGit(cwd: string, args: string[]) {
  const result = Bun.spawnSync(["git", "-C", cwd, ...args])
  return result.exitCode === 0 ? result.stdout.toString() : undefined
}

// Same resolution as script/godfile.ts: the merge-base with the target branch, else the ref itself.
export function resolveBase(cwd: string, baseRef: string) {
  const base = tryGit(cwd, ["merge-base", baseRef, "HEAD"])?.trim()
  if (base) return base
  return tryGit(cwd, ["rev-parse", "--verify", `${baseRef}^{commit}`])?.trim()
}

// The change from `base` to the working tree, or, when `head` is given, from `base` to that commit (history scans).
export function readDiff(cwd: string, base: string, head?: string): Diff {
  const range = head ? [base, head] : [base]
  const entries = parseRaw(git(cwd, ["diff", "--raw", "-z", "-M", "-l0", "--no-abbrev", ...range]))
  const binary = parseBinary(git(cwd, ["diff", "--numstat", "-z", "-M", "-l0", ...range]))
  const patch = parsePatch(
    git(cwd, ["-c", "core.quotepath=off", "diff", "-U0", "-M", "-l0", "--no-color", "--no-ext-diff", "--no-prefix", ...range]),
  )
  const sizes = blobSizes(
    cwd,
    entries.filter((entry) => entry.status !== "D" && entry.mode !== "160000").map((entry) => entry.sha),
  )
  const tracked = entries.map((entry) => ({
    path: entry.path,
    status: entry.status,
    from: entry.from,
    added: patch.added.get(entry.path) ?? [],
    removedLines: patch.removedBy.get(entry.path) ?? [],
    mode: entry.mode,
    size: sizes.get(entry.sha),
    binary: binary.has(entry.path),
    // Only an executable can be missing its shebang, so only those blobs are read.
    shebang: entry.mode === "100755" ? (tryGit(cwd, ["cat-file", "blob", entry.sha]) ?? "").startsWith("#!") : undefined,
  }))
  return { changes: head ? tracked : [...tracked, ...untracked(cwd)], removed: patch.removed }
}

// `git diff --raw -z --no-abbrev`: `:<old mode> <new mode> <old sha> <new sha> <status>` then the path (two for R and C).
export function parseRaw(output: string) {
  const fields = output.split("\0")
  const entries: { path: string; status: string; from: string | undefined; mode: string; sha: string }[] = []
  for (let index = 0; index < fields.length && fields[index]?.startsWith(":"); ) {
    const meta = fields[index]!.slice(1).split(" ")
    const status = (meta[4] ?? "").charAt(0)
    const pair = status === "R" || status === "C"
    entries.push({
      status,
      from: pair ? fields[index + 1] : undefined,
      path: (pair ? fields[index + 2] : fields[index + 1]) ?? "",
      mode: meta[1] ?? "100644",
      sha: meta[3] ?? "",
    })
    index += pair ? 3 : 2
  }
  return entries.filter((entry) => entry.path.length > 0)
}

// `git diff --numstat -z`: `<added>\t<deleted>\t<path>`, or `<added>\t<deleted>\t` then two paths for a rename. A binary file has `-` counts.
export function parseBinary(output: string) {
  const fields = output.split("\0")
  const binary = new Set<string>()
  for (let index = 0; index < fields.length && fields[index]; ) {
    const columns = fields[index]!.split("\t")
    const renamed = columns[2] === ""
    const file = renamed ? fields[index + 2] : columns[2]
    if (columns[0] === "-" && file) binary.add(file)
    index += renamed ? 3 : 1
  }
  return binary
}

function blobSizes(cwd: string, shas: string[]) {
  const sizes = new Map<string, number>()
  const wanted = shas.filter((sha) => sha.length > 0 && !/^0+$/.test(sha))
  if (wanted.length === 0) return sizes
  const output = Bun.spawnSync(["git", "-C", cwd, "cat-file", "--batch-check"], {
    stdin: Buffer.from(wanted.join("\n") + "\n"),
  }).stdout.toString()
  for (const line of output.split("\n")) {
    const columns = line.split(" ")
    if (columns[1] === "blob") sizes.set(columns[0]!, Number(columns[2]))
  }
  return sizes
}

// Unified diff (-U0, --no-prefix) to added lines per new path plus the set of removed lines.
export function parsePatch(patch: string) {
  const added = new Map<string, Added[]>()
  const removed = new Map<string, number>()
  const removedBy = new Map<string, string[]>()
  let current: string | undefined
  let previous: string | undefined
  let line = 0
  let inHunk = false
  for (const text of patch.split("\n")) {
    if (text.startsWith("diff --git ")) {
      current = undefined
      previous = undefined
      inHunk = false
      continue
    }
    if (!inHunk && text.startsWith("--- ")) {
      previous = text === "--- /dev/null" ? undefined : text.slice(4)
      continue
    }
    if (!inHunk && text.startsWith("+++ ")) {
      current = text === "+++ /dev/null" ? undefined : text.slice(4)
      continue
    }
    const hunk = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@/.exec(text)
    if (hunk) {
      inHunk = true
      line = Number(hunk[1])
      continue
    }
    if (!inHunk) continue
    if (text.startsWith("+")) {
      if (current) added.set(current, [...(added.get(current) ?? []), { line, text: text.slice(1) }])
      line += 1
      continue
    }
    if (text.startsWith("-")) {
      removed.set(text.slice(1).trim(), (removed.get(text.slice(1).trim()) ?? 0) + 1)
      const owner = current ?? previous
      if (owner) removedBy.set(owner, [...(removedBy.get(owner) ?? []), text.slice(1).trim()])
    }
  }
  return { added, removed, removedBy }
}

// A new file that git does not track yet has no diff. Read it whole so a local run sees it.
function untracked(cwd: string): Change[] {
  return git(cwd, ["ls-files", "-o", "--exclude-standard", "-z"])
    .split("\0")
    .filter((file) => file.length > 0)
    .flatMap((file) => {
      const text = readText(path.join(cwd, file))
      if (text === undefined) return []
      return [
        {
          path: file,
          status: "A",
          from: undefined,
          added: text.split("\n").map((content, index) => ({ line: index + 1, text: content })),
          mode: (statSync(path.join(cwd, file)).mode & 0o111) === 0 ? "100644" : "100755",
          size: Buffer.byteLength(text),
          binary: false,
          shebang: text.startsWith("#!"),
        },
      ]
    })
}

function readText(file: string) {
  try {
    const buffer = readFileSync(file)
    if (buffer.length > MAX_UNTRACKED_BYTES || buffer.includes(0)) return undefined
    return buffer.toString("utf8")
  } catch {
    return undefined
  }
}

// Pure evaluation: rules and a diff in, findings out. No git, no disk.

import type { Diff } from "./diff"
import { globs, inScope, lineHits, type Rule } from "./rule"

export type Config = {
  // Generated or vendored paths that added-lines rules skip unless the rule sets generated = "include".
  generated: string[]
  // Paths no added-lines rule reads (the engine's own samples).
  exclude: string[]
  // Named glob lists a rule refers to as `$name` (see expandSets in rule.ts).
  sets: Record<string, string[]>
}

export type Finding = {
  rule: string
  severity: "gate" | "warn"
  path: string
  line: number | undefined
  message: string
  // added-lines only: the offending added line and where `match` hit in it, [start, end) in UTF-16 units, so a
  // viewer can underline the hit without running the regex again.
  excerpt?: string
  match?: [number, number]
}

// `guardrail-ignore: <rule id> <reason>` on the offending line. Without a reason it does not count.
const IGNORE = /guardrail-ignore:\s*(\S+)\s+\S/

export function evaluate(input: { rules: Rule[]; config: Config; diff: Diff; approved: string[] }) {
  return input.rules.flatMap((rule) => {
    // The label `guardrail-approved:<rule id>` clears a rule of any kind: a JSON line cannot carry an ignore comment.
    if (input.approved.includes(rule.id)) return []
    if (rule.on === "changed-paths") return pathFindings(rule, input)
    if (rule.on === "line-balance") return balanceFindings(rule, input)
    return lineFindings(rule, input)
  })
}

function pathFindings(rule: Rule, input: Parameters<typeof evaluate>[0]): Finding[] {
  if (input.diff.changes.some((change) => globs(rule.requiresChanged, change.path))) return []
  return input.diff.changes
    .filter((change) => rule.statuses.length === 0 || rule.statuses.includes(change.status))
    .filter((change) => inScope(rule, change.path) || (change.from !== undefined && inScope(rule, change.from)))
    .filter((change) => !rule.leavesScope || change.status === "D" || (change.from !== undefined && !inScope(rule, change.path)))
    .filter((change) => rule.modes.length === 0 || rule.modes.includes(change.mode ?? "100644"))
    .filter((change) => rule.minBytes === undefined || (change.size ?? 0) >= rule.minBytes)
    .filter((change) => rule.binary === undefined || (change.binary ?? false) === rule.binary)
    .filter((change) => !rule.noShebang || !(change.shebang ?? false))
    .filter((change) => !rule.touches || [...change.added.map((added) => added.text), ...(change.removedLines ?? [])].some((text) => rule.touches?.test(text)))
    .map((change) => ({
      rule: rule.id,
      severity: rule.severity,
      path: change.path,
      line: undefined,
      message: rule.message,
    }))
}

function lineFindings(rule: Rule, input: Parameters<typeof evaluate>[0]): Finding[] {
  // Each removed line excuses one identical added line for this rule, so deleting one `// @ts-ignore` does not let
  // a new one through for free.
  const moved = new Map(input.diff.removed)
  const excused = (text: string) => {
    const left = moved.get(text.trim()) ?? 0
    if (left > 0) moved.set(text.trim(), left - 1)
    return left > 0
  }
  return input.diff.changes
    .filter((change) => inScope(rule, change.path) && !globs(input.config.exclude, change.path))
    .filter((change) => rule.generated === "include" || !globs(input.config.generated, change.path))
    .flatMap((change) =>
      change.added
        .filter((added) => lineHits(rule, added.text))
        .filter((added) => IGNORE.exec(added.text)?.[1] !== rule.id)
        .filter((added) => !excused(added.text))
        .filter((added) => !rule.newOnly || !renamedOnly(rule, added.text, change.removedLines ?? []))
        .map((added) => ({
          rule: rule.id,
          severity: rule.severity,
          path: change.path,
          line: added.line,
          message: rule.message,
          excerpt: added.text,
          match: hitRange(rule, added.text),
        })),
    )
}

// Lines a file loses minus lines it gains, counting only lines the rule matches. A removed line that reappears
// anywhere else in the change was moved, not removed. Deleted files are the business of path rules.
function balanceFindings(rule: Rule, input: Parameters<typeof evaluate>[0]): Finding[] {
  const gained = new Set(input.diff.changes.flatMap((change) => change.added.map((added) => added.text.trim())))
  return input.diff.changes
    .filter((change) => change.status !== "D" && inScope(rule, change.path) && !globs(input.config.exclude, change.path))
    .filter((change) => rule.generated === "include" || !globs(input.config.generated, change.path))
    .filter((change) => {
      const lost = (change.removedLines ?? []).filter((text) => lineHits(rule, text) && !gained.has(text)).length
      const added = change.added.filter((line) => lineHits(rule, line.text)).length
      return lost - added >= (rule.minNetRemoved ?? 1)
    })
    .map((change) => ({ rule: rule.id, severity: rule.severity, path: change.path, line: undefined, message: rule.message }))
}

function hitRange(rule: Rule, text: string): [number, number] | undefined {
  const hit = rule.match?.exec(text)
  return hit ? [hit.index, hit.index + hit[0].length] : undefined
}

// A version bump removes the line that names the same dependency. Only meaningful with new_only.
function renamedOnly(rule: Rule, text: string, removed: string[]) {
  const name = rule.match?.exec(text)?.[1]
  return name !== undefined && removed.some((line) => rule.match?.exec(line)?.[1] === name)
}

// A guard rule is one TOML file in script/guards/rules/. The id is the file name. A rule without positive and negative
// samples does not load, so every rule that runs has been shown to fire and to stay quiet.

export const GROUPS = ["tests", "silenced", "secrets", "leftovers", "dependencies", "workflows", "hygiene"] as const
export type Group = (typeof GROUPS)[number]

export type Rule = {
  id: string
  // What the rule is about, for browsing. Display only; the engine never reads it.
  group: Group
  // One sentence on what the rule looks at, for a rule browser. Optional until every rule has one.
  summary: string | undefined
  severity: "gate" | "warn"
  // added-lines: `match` runs on each added line. changed-paths: the rule fires on a changed path inside `paths`.
  // line-balance: in one file, lines matching `match` removed minus lines matching it added reaches `minNetRemoved`.
  on: "added-lines" | "changed-paths" | "line-balance"
  paths: string[]
  exclude: string[]
  // Whether the shared generated-file list is skipped for this rule. A conflict marker is a defect even in generated code.
  generated: "skip" | "include"
  // Git status letters (A, M, D, R, C) a changed-paths rule applies to. Empty means all.
  statuses: string[]
  // changed-paths only. The file must have one of these git modes (100755 executable, 120000 symlink, 160000 submodule).
  modes: string[]
  // changed-paths only. The file must be at least this many bytes.
  minBytes: number | undefined
  // changed-paths only. true: only binary files. false: only text files.
  binary: boolean | undefined
  // changed-paths only. true: only files that do not start with a #! line.
  noShebang: boolean
  // line-balance only.
  minNetRemoved: number | undefined
  // changed-paths only. The rule stays quiet when any change touches one of these globs (the lockfile moved with the manifest).
  requiresChanged: string[]
  // changed-paths only. The file must have an added or removed line matching this.
  touches: RegExp | undefined
  match: RegExp | undefined
  // Added lines whose trimmed text starts with one of these are comments or docs, not code; `match` never sees them.
  skipComments: string[]
  // added-lines only. The first capture group of `match` names the thing the line adds; a line is skipped when a removed
  // line in the same file names the same thing (a version bump), so only genuinely new names are reported.
  newOnly: boolean
  // changed-paths only. A rename or copy counts when its old path is in scope and its new path is not, so moving a test out
  // of the test globs is a deletion; a rename that stays in scope is still a move.
  leavesScope: boolean
  message: string
  // added-lines: sample lines. changed-paths: sample paths.
  positive: string[]
  negative: string[]
}

export function parseRule(file: string, text: string): Rule | string {
  const raw = parseToml(text)
  if (typeof raw === "string") return `${file}: ${raw}`
  const id = raw.id
  if (typeof id !== "string" || `${id}.toml` !== file) return `${file}: id must equal the file name`
  const group = GROUPS.find((name) => name === raw.group)
  if (!group) return `${file}: group must be one of ${GROUPS.join(", ")}`
  const summary = raw.summary
  if (summary !== undefined && typeof summary !== "string") return `${file}: summary must be a string`
  const severity = raw.severity
  if (severity !== "gate" && severity !== "warn") return `${file}: severity must be "gate" or "warn"`
  const on = raw.on
  if (on !== "added-lines" && on !== "changed-paths" && on !== "line-balance") {
    return `${file}: on must be "added-lines", "changed-paths" or "line-balance"`
  }
  const paths = strings(raw.paths)
  if (!paths || paths.length === 0) return `${file}: paths must be a non-empty list of globs`
  const exclude = strings(raw.exclude ?? [])
  if (!exclude) return `${file}: exclude must be a list of globs`
  const statuses = strings(raw.statuses ?? [])
  if (!statuses) return `${file}: statuses must be a list of git status letters`
  const modes = strings(raw.modes ?? [])
  if (!modes) return `${file}: modes must be a list of git modes`
  const minBytes = raw.min_bytes
  if (minBytes !== undefined && (typeof minBytes !== "number" || !Number.isSafeInteger(minBytes) || minBytes < 1)) {
    return `${file}: min_bytes must be a positive integer`
  }
  const binary = raw.binary
  if (binary !== undefined && typeof binary !== "boolean") return `${file}: binary must be true or false`
  const noShebang = raw.no_shebang ?? false
  if (typeof noShebang !== "boolean") return `${file}: no_shebang must be true or false`
  const minNetRemoved = raw.min_net_removed
  if (minNetRemoved !== undefined && (typeof minNetRemoved !== "number" || !Number.isSafeInteger(minNetRemoved) || minNetRemoved < 1)) {
    return `${file}: min_net_removed must be a positive integer`
  }
  const requiresChanged = strings(raw.requires_changed ?? [])
  if (!requiresChanged) return `${file}: requires_changed must be a list of globs`
  const touches = raw.touches === undefined ? undefined : compile(raw.touches, typeof raw.flags === "string" ? raw.flags : "")
  if (raw.touches !== undefined && !touches) return `${file}: touches is not a valid regular expression`
  const generated = raw.generated ?? "skip"
  if (generated !== "skip" && generated !== "include") return `${file}: generated must be "skip" or "include"`
  const message = raw.message
  if (typeof message !== "string" || message.trim().length === 0) return `${file}: message is required`
  const positive = strings(raw.positive)
  const negative = strings(raw.negative)
  if (!positive || !negative || positive.length === 0 || negative.length === 0) {
    return `${file}: positive and negative samples are required`
  }
  const flags = raw.flags ?? ""
  if (flags !== "" && flags !== "i") return `${file}: flags may only be "i" (case-insensitive)`
  const skipComments = strings(raw.skip_comments ?? [])
  if (!skipComments) return `${file}: skip_comments must be a list of line prefixes`
  const newOnly = raw.new_only ?? false
  if (typeof newOnly !== "boolean") return `${file}: new_only must be true or false`
  const leavesScope = raw.leaves_scope ?? false
  if (typeof leavesScope !== "boolean") return `${file}: leaves_scope must be true or false`
  if (leavesScope && on !== "changed-paths") return `${file}: leaves_scope needs a changed-paths rule`
  const match = raw.match === undefined ? undefined : compile(raw.match, flags)
  if (raw.match !== undefined && !match) return `${file}: match is not a valid regular expression`
  if (on !== "changed-paths" && !match) return `${file}: an ${on} rule needs a match`
  if (newOnly && (on !== "added-lines" || !match || !/\((?!\?)/.test(match.source))) return `${file}: new_only needs an added-lines rule whose match has a capture group`
  if (on === "line-balance" && minNetRemoved === undefined) return `${file}: a line-balance rule needs min_net_removed`
  if (on !== "line-balance" && minNetRemoved !== undefined) return `${file}: min_net_removed is for line-balance rules`
  const fileFilters =
    modes.length > 0 || minBytes !== undefined || binary !== undefined || noShebang || requiresChanged.length > 0 || touches !== undefined
  if (on === "added-lines" && fileFilters) return `${file}: modes, min_bytes, binary, no_shebang, requires_changed and touches are for changed-paths rules`
  if (on === "changed-paths" && match) return `${file}: a changed-paths rule matches by paths, not by match`
  return {
    id,
    group,
    summary,
    severity,
    on,
    paths,
    exclude,
    generated,
    statuses,
    modes,
    minBytes,
    binary,
    noShebang,
    minNetRemoved,
    requiresChanged,
    touches,
    match,
    skipComments,
    newOnly,
    leavesScope,
    message,
    positive,
    negative,
  }
}

export function inScope(rule: Rule, path: string) {
  return globs(rule.paths, path) && !globs(rule.exclude, path)
}

export function globs(patterns: string[], path: string) {
  return patterns.some((pattern) => new Bun.Glob(pattern).match(path))
}

export function lineHits(rule: Rule, text: string) {
  const code = text.trimStart()
  if (rule.skipComments.some((prefix) => code.startsWith(prefix))) return false
  return rule.match?.test(text) ?? false
}

// `$name` in paths, exclude or requires_changed stands for the glob list `[sets] name` in config.toml, so a test-file
// glob lives in one place. An unknown name is an error: it would silently match nothing.
export function expandSets(rule: Rule, sets: Record<string, string[]>): Rule | string {
  const unknown = [...rule.paths, ...rule.exclude, ...rule.requiresChanged].find((glob) => glob.startsWith("$") && !sets[glob.slice(1)])
  if (unknown) return `${rule.id}: ${unknown} is not defined under [sets] in config.toml`
  const expand = (list: string[]) => list.flatMap((glob) => (glob.startsWith("$") ? sets[glob.slice(1)]! : [glob]))
  return { ...rule, paths: expand(rule.paths), exclude: expand(rule.exclude), requiresChanged: expand(rule.requiresChanged) }
}

// Runs the rule's own samples. Returns one error per sample that behaves wrongly. A changed-paths rule's samples are
// paths, so they check the path scope only; its mode, size and content filters are covered by the pack's golden test.
export function selfCheck(rule: Rule) {
  const hits = (sample: string) => (rule.on === "changed-paths" ? inScope(rule, sample) : lineHits(rule, sample))
  return [
    ...rule.positive.filter((sample) => !hits(sample)).map((sample) => `${rule.id}: positive sample does not fire: ${sample}`),
    ...rule.negative.filter((sample) => hits(sample)).map((sample) => `${rule.id}: negative sample fires: ${sample}`),
  ]
}

function parseToml(text: string): Record<string, unknown> | string {
  try {
    return Bun.TOML.parse(text) as Record<string, unknown>
  } catch (error) {
    return `invalid TOML (${String(error)})`
  }
}

function compile(value: unknown, flags = "") {
  if (typeof value !== "string") return undefined
  try {
    return new RegExp(value, flags)
  } catch {
    return undefined
  }
}

function strings(value: unknown) {
  if (!Array.isArray(value)) return undefined
  return value.every((item) => typeof item === "string") ? (value as string[]) : undefined
}
